-- CreateSchema
CREATE SCHEMA IF NOT EXISTS "core";
SET search_path TO "core";
CREATE TYPE "OrganizationType" AS ENUM ('BUYER', 'SELLER', 'BOTH');
CREATE TYPE "UserRole" AS ENUM ('BUYER', 'SALES', 'ADMIN');
CREATE TYPE "OrganizationStatus" AS ENUM ('ACTIVE', 'SUSPENDED', 'PENDING');
CREATE TYPE "CatalogVisibility" AS ENUM ('PUBLIC', 'PRIVATE');
CREATE TYPE "ProductStatus" AS ENUM ('DRAFT', 'ACTIVE', 'ARCHIVED');
CREATE TYPE "MediaType" AS ENUM ('IMAGE', 'VIDEO');
CREATE TYPE "RFQStatus" AS ENUM ('DRAFT', 'OPEN', 'QUOTED', 'NEGOTIATING', 'ACCEPTED', 'REJECTED', 'CANCELLED', 'EXPIRED');
CREATE TYPE "QuoteStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'REVISED', 'ACCEPTED', 'REJECTED', 'EXPIRED', 'WITHDRAWN');
CREATE TYPE "SeptlionOfferStatus" AS ENUM ('DRAFT', 'INTERNAL_REVIEW', 'ISSUED', 'REVISION_REQUESTED', 'REVISED', 'ACCEPTED', 'EXPIRED', 'REJECTED', 'WITHDRAWN');
CREATE TYPE "SeptlionOfferRevisionStatus" AS ENUM ('DRAFT', 'ISSUED', 'ACCEPTED', 'SUPERSEDED');
CREATE TYPE "QuoteRevisionStatus" AS ENUM ('PROPOSED', 'ACCEPTED', 'REJECTED', 'SUPERSEDED');
CREATE TYPE "OrderIntentStatus" AS ENUM ('CREATED', 'CONFIRMED', 'CANCELLED');
CREATE TYPE "TradeTransactionStatus" AS ENUM ('PENDING_COMMIT', 'COMMITTED', 'IN_EXECUTION', 'READY_TO_SHIP', 'SHIPPED', 'IN_TRANSIT', 'DELIVERED', 'RECEIPT_REVIEW', 'COMPLETED', 'ON_HOLD', 'CLAIM_OPEN', 'CANCELLED');
CREATE TYPE "MilestoneStatus" AS ENUM ('PENDING', 'IN_PROGRESS', 'COMPLETED', 'BLOCKED', 'CANCELLED');
CREATE TYPE "ReceiptStatus" AS ENUM ('PENDING', 'ACCEPTED', 'ISSUE_REPORTED');
CREATE TYPE "ClaimStatus" AS ENUM ('OPEN', 'UNDER_REVIEW', 'RESOLVED', 'REJECTED', 'CLOSED');
CREATE TYPE "ChangeOrderStatus" AS ENUM ('PROPOSED', 'APPROVED', 'REJECTED', 'SUPERSEDED');
CREATE TYPE "TradeEventVisibility" AS ENUM ('INTERNAL', 'BUYER', 'COUNTERPARTY');
CREATE TYPE "AuditAction" AS ENUM ('CREATE', 'UPDATE', 'DELETE', 'STATUS_CHANGE', 'LOGIN', 'LOGOUT', 'RFQ_CREATED', 'RFQ_UPDATED', 'QUOTE_CREATED', 'QUOTE_SUBMITTED', 'QUOTE_UPDATED', 'ORDER_INTENT_CREATED', 'ORDER_INTENT_UPDATED', 'DOCUMENT_UPLOADED', 'MESSAGE_SENT', 'NOTIFICATION_READ');
CREATE TYPE "WorkspaceEntityType" AS ENUM ('RFQ', 'QUOTE', 'ORDER_INTENT', 'TRANSACTION');
CREATE TYPE "DocumentStatus" AS ENUM ('PENDING', 'READY', 'QUARANTINED', 'DELETED');
CREATE TYPE "MessageType" AS ENUM ('TEXT', 'SYSTEM', 'DOCUMENT');
CREATE TYPE "NotificationType" AS ENUM ('RFQ', 'QUOTE', 'NEGOTIATION', 'DOCUMENT', 'MESSAGE', 'ORDER_INTENT', 'TRANSACTION', 'CLAIM', 'SYSTEM');
CREATE TYPE "OutboxStatus" AS ENUM ('PENDING', 'PROCESSING', 'PROCESSED', 'FAILED');
CREATE TYPE "MaritimeRfqStatus" AS ENUM ('ESTIMATED', 'SUBMITTED', 'EXPIRED', 'CANCELLED');
CREATE TYPE "DemandSignalType" AS ENUM ('TENDER', 'RFQ', 'AUCTION');
CREATE TYPE "DemandSignalStatus" AS ENUM ('WATCH', 'RESOLVE_BUYER', 'QUALIFY_NOW', 'ARCHIVED');
CREATE TYPE "IntelligenceVerificationStatus" AS ENUM ('UNVERIFIED', 'SOURCE_CONFIRMED', 'CROSS_VERIFIED', 'HUMAN_VERIFIED');
CREATE TYPE "RequirementSource" AS ENUM ('AI_COMPOSER', 'PRODUCT_FEED', 'REORDER', 'INTERNAL');
CREATE TYPE "WhatsAppReachability" AS ENUM ('UNCONFIRMED', 'CONFIRMED', 'UNREACHABLE');
CREATE TYPE "RequirementStatus" AS ENUM ('DRAFT', 'NEEDS_CLARIFICATION', 'QUALIFIED', 'SUPPLY_READY', 'ARCHIVED');
CREATE TYPE "OpportunityStatus" AS ENUM ('DISCOVERED', 'BUYER_RESOLUTION', 'QUALIFICATION', 'SUPPLY_MATCHING', 'DEAL_BUILDING', 'AWAITING_APPROVAL', 'APPROVED', 'WON', 'LOST', 'ARCHIVED');
CREATE TYPE "AgentRunStatus" AS ENUM ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'NEEDS_HUMAN');
CREATE TYPE "ApprovalDecision" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "ApprovalAction" AS ENUM ('START_SUPPLY_MATCHING', 'BUILD_DEAL', 'SEND_RFQ', 'SEND_QUOTE', 'ACCEPT_COMMERCIAL_TERMS', 'CREATE_ORDER_INTENT', 'EXTERNAL_COMMITMENT');
CREATE TABLE "Organization" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"legalName" TEXT,"country" TEXT,"organizationType" "OrganizationType" NOT NULL DEFAULT 'BOTH',"status" "OrganizationStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"firstName" TEXT,"lastName" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"sessionVersion" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Membership" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"role" "UserRole" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Membership_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RefreshSession" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RefreshSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Sector" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Sector_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SectorPolicy" ("id" TEXT NOT NULL,"sectorId" TEXT NOT NULL,"defaultCurrency" TEXT NOT NULL DEFAULT 'USD',"defaultUnit" TEXT NOT NULL DEFAULT 'MT',"minimumOrderQty" DECIMAL(18,4),"requiresCertificate" BOOLEAN NOT NULL DEFAULT false,"requiresOrigin" BOOLEAN NOT NULL DEFAULT false,"requiresPackingList" BOOLEAN NOT NULL DEFAULT false,"shippingRules" JSONB,"requiredDocuments" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SectorPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Product" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"sectorId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"status" "ProductStatus" NOT NULL DEFAULT 'DRAFT',"visibility" "CatalogVisibility" NOT NULL DEFAULT 'PRIVATE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SKU" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"productId" TEXT NOT NULL,"skuCode" TEXT NOT NULL,"name" TEXT NOT NULL,"unit" TEXT NOT NULL,"minimumOrderQty" DECIMAL(18,4) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'USD',"specifications" JSONB,"shipping" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SKU_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Media" ("id" TEXT NOT NULL,"skuId" TEXT NOT NULL,"type" "MediaType" NOT NULL,"url" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Media_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RFQ" ("id" TEXT NOT NULL,"requirementId" TEXT,"buyerOrgId" TEXT NOT NULL,"supplierOrgId" TEXT,"sectorId" TEXT NOT NULL,"reference" TEXT NOT NULL,"status" "RFQStatus" NOT NULL DEFAULT 'DRAFT',"deliveryCountry" TEXT,"deliveryPort" TEXT,"incoterm" TEXT,"requestedDocuments" JSONB,"requestedDate" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RFQ_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RFQItem" ("id" TEXT NOT NULL,"rfqId" TEXT NOT NULL,"skuId" TEXT NOT NULL,"quantity" DECIMAL(18,4) NOT NULL,"unit" TEXT NOT NULL,"targetPrice" DECIMAL(18,4),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RFQItem_pkey" PRIMARY KEY ("id"));
